#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Fragments;
using MVZ2.Vanilla;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using PVZEngine;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [EntityBehaviourDefinition(VanillaEnemyNames.ghost)]
    public class Ghost : AIEntityBehaviour
    {
        public Ghost(string nsp, string name) : base(nsp, name)
        {
            AddAura(new GhostAura());
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            if (!entity.HasBuff<GhostBuff>())
            {
                entity.AddBuff<GhostBuff>();
            }
            var buff = entity.AddBuff<FlyBuff>();
            buff.SetProperty(FlyBuff.PROP_TARGET_HEIGHT, 1f);
            SetStateTimer(entity, new FrameTimer(CAST_COOLDOWN));
            DeactivatePossession(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            if (entity.IsDead)
                return;
            if (entity.State == STATE_MELEE_ATTACK)
                return;
            if (GetPossessingEntity(entity) != null)
                return;
            if (IsPossessingEntity(entity))
                return;
            var stateTimer = GetStateTimer(entity);
            var attackSpeed = entity.GetAttackSpeed();
            if (stateTimer.RunToExpiredAndNotNull(attackSpeed))
            {
                var target = entity.Level.FindEntities(e => CanPossess(entity, e) && !ExistPossessingGhost(entity, e)).RandomTake(1, entity.RNG);
                foreach (var id in target)
                {
                    entity.SetCasting(true);
                    entity.Spawn(VanillaEffectID.ghostChain, entity.GetCenter())?.Let(c =>
                    {
                        c.SetParent(entity);
                        GhostChain.SetPossessingEntity(c, new EntityID(id));
                    });
                    SetPossessingEntity(entity, new EntityID(id));
                }
                stateTimer.Reset();
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            if (!entity.HasBuff<GhostBuff>())
            {
                entity.AddBuff<GhostBuff>();
            }

            var targetID = GetPossessingEntity(entity);
            var target = targetID?.GetEntity(entity.Level);
            if (target.ExistsAndAlive())
            {
                if (IsPossessingEntity(entity))
                {
                    // 附身时无法被发现
                    entity.SetCenter(target.GetCenter());
                    entity.Velocity = Vector3.zero;
                    if (!entity.HasBuff<GhostPossessingBuff>())
                    {
                        entity.AddBuff<GhostPossessingBuff>();
                    }
                    // 解除附身的条件
                    if (ShouldExitPossess(entity, target, false))
                    {
                        SetPossessingEntity(entity, null);
                    }
                    entity.SetCasting(false);
                }
            }
            else
            {
                // 解除附身
                if (entity.HasBuff<GhostPossessingBuff>())
                {
                    entity.RemoveBuffs<GhostPossessingBuff>();
                    DeactivatePossession(entity);
                    entity.PlaySound(VanillaSoundID.chainsBreak);
                    entity.CreateFragmentAndPlay(VanillaFragmentID.ghostChain, 50);
                    entity.Velocity += entity.GetFacingDirection() * -3;
                }
                entity.SetCasting(false);
                SetPossessingEntity(entity, null);
            }
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (!GhostBuff.IsEverIlluminated(entity) && !info.Effects.HasEffect(VanillaDamageEffects.WHACK) && !entity.Level.IsIZombie())
            {
                Global.Saves.Unlock(VanillaUnlockID.ghostBuster);
                Global.Saves.SaveToFile(); // 完成成就后保存游戏。
            }
        }

        #region 附身
        private bool CanPossess(Entity self, Entity target)
        {
            if (!ValidTarget(self, target))
                return false;
            if (target.IsNotActiveEnemy())
                return false;
            // 无视已有GhostBuff的怪物
            if (target.HasBuff<GhostBuff>())
                return false;
            return true;
        }
        public static bool ShouldExitPossess(Entity self, Entity target, bool chain)
        {
            if (!ValidTarget(self, target))
                return true;
            // 自己被照亮，对于锁链而言无视此条件
            if (self.IsIlluminated() && IsIlluminatedByGlowstone(self) && !chain)
                return true;
            // 其他幽灵
            if (target.IsEntityOf(self.GetDefinitionID()))
                return true;
            return false;
        }
        public static bool ValidTarget(Entity self, Entity target)
        {
            // 白天
            if (self.Level.IsDay())
                return false;
            if (target == null)
                return false;
            if (target.IsDead)
                return false;
            // 仅附身怪物
            if (target.Type != EntityTypes.ENEMY)
                return false;
            // 敌对
            if (self.IsHostile(target))
                return false;
            // 控制状态
            if (target.IsAIFrozen())
                return false;
            // 离场的怪物
            if (target.Position.x <= VanillaLevelExt.GetAttackBorderX(false))
                return false;
            if (!Detection.CanDetect(target))
                return false;
            // 被照亮的怪物
            if (target.IsIlluminated() && IsIlluminatedByGlowstone(target))
                return false;
            return true;
        }
        private bool ExistPossessingGhost(Entity self, Entity target)
        {
            foreach (var entity in self.Level.FindEntities(e => e.IsEntityOf(VanillaEnemyID.ghost) && e.ExistsAndAlive() && e.IsFriendly(self)))
            {
                if (GetPossessingEntity(entity)?.GetEntity(entity.Level) == target && entity != self)
                {
                    return true;
                }
            }
            return false;
        }
        public static bool IsPossessingEntity(Entity? self)
        {
            if (!self.ExistsAndAlive())
                return false;
            if (self.IsAIFrozen())
                return false;
            if (!IsPossessionActivated(self))
                return false;
            var targetID = GetPossessingEntity(self);
            var target = targetID?.GetEntity(self.Level);
            return target.ExistsAndAlive();
        }
        public static bool IsIlluminatedByGlowstone(Entity self)
        {
            foreach (var glowstone in self.GetIlluminationLightSources())
            {
                if (glowstone.IsEntityOf(VanillaContraptionID.glowstone))
                    return true;
            }
            return false;
        }
        public class GhostAura : AuraEffectDefinition
        {
            public GhostAura() : base(VanillaBuffID.Enemy.ghost, 3)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var entity = auraEffect.Source as Entity;
                if (entity == null)
                    return;
                if (!IsPossessingEntity(entity))
                    return;
                var targetID = GetPossessingEntity(entity);
                var possessTarget = targetID?.GetEntity(entity.Level);
                if (possessTarget == null)
                    return;
                results.Add(possessTarget);
            }
        }
        #endregion
        public static readonly NamespaceID ID = VanillaEnemyID.ghost;
        public static EntityID? GetPossessingEntity(Entity entity) => entity.GetBehaviourField<EntityID>(PROP_TARGET_ENTITY);
        public static void SetPossessingEntity(Entity entity, EntityID? value) => entity.SetBehaviourField(PROP_TARGET_ENTITY, value);
        public static void SetStateTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_STATE_TIMER, timer);
        public static FrameTimer? GetStateTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_STATE_TIMER);
        public static void ActivatePossession(Entity entity) => entity.SetBehaviourField(PROP_ACTIVATE_POSSESSION, true);
        public static void DeactivatePossession(Entity entity) => entity.SetBehaviourField(PROP_ACTIVATE_POSSESSION, false);
        public static bool IsPossessionActivated(Entity entity) => entity.GetBehaviourField<bool>(PROP_ACTIVATE_POSSESSION);
        private const int CAST_COOLDOWN = 90;
        public const int STATE_MELEE_ATTACK = VanillaEnemyStates.MELEE_ATTACK;
        public static readonly VanillaEntityPropertyMeta<EntityID> PROP_TARGET_ENTITY = new VanillaEntityPropertyMeta<EntityID>("target_entity");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("StateTimer");
        public static readonly VanillaEntityPropertyMeta<bool> PROP_ACTIVATE_POSSESSION = new VanillaEntityPropertyMeta<bool>("activate_possession");
    }
}
